class LockBoundedBuffer {
    Queue<Integer> queue = new LinkedList<>(); int capacity;
    Lock lock = new ReentrantLock();
    Condition notFull = lock.newCondition(), notEmpty = lock.newCondition();
    LockBoundedBuffer(int c) { capacity = c; }
    void put(int v) throws InterruptedException {
        lock.lock();
        try { while (queue.size()==capacity) notFull.await(); queue.add(v); notEmpty.signalAll(); }
        finally { lock.unlock(); }
    }
    int take() throws InterruptedException {
        lock.lock();
        try { while (queue.isEmpty()) notEmpty.await(); int v = queue.poll(); notFull.signalAll(); return v; }
        finally { lock.unlock(); }
    }
}

void recursiveWork(ReentrantLock lock, int depth) {
