ReentrantLock lock = new ReentrantLock();
Map<String,Integer> stock = new HashMap<>(Map.of("A",100,"B",100));
boolean sell(String item, int qty) {
    lock.lock();
    try { int cur = stock.get(item); if (cur < qty) return false; stock.put(item, cur-qty); return true; }
    finally { lock.unlock(); }
}
void restock(String item, int qty) { lock.lock(); try { stock.merge(item, qty, Integer::sum); } finally { lock.unlock(); } }
