Map<String, ReentrantLock> locks = new HashMap<>();
Map<String, Integer> balances = new HashMap<>();
for (String konto : List.of("A","B","C","D","E")) { locks.put(konto, new ReentrantLock()); balances.put(konto, 1000); }
void transfer(String from, String to, int amount) {
    String pierwsze = from.compareTo(to) < 0 ? from : to;
    String drugie = from.compareTo(to) < 0 ? to : from;
    locks.get(pierwsze).lock();
    try {
        locks.get(drugie).lock();
        try { balances.merge(from, -amount, Integer::sum); balances.merge(to, amount, Integer::sum); }
        finally { locks.get(drugie).unlock(); }
    } finally { locks.get(pierwsze).unlock(); }
}
// 10 watkow x 20 losowych transferow, zweryfikuj suma(balances.values()) == 5000
